import os,json,hashlib,subprocess,time,sys
from pathlib import Path
from datetime import datetime,timezone
B=Path('/private/tmp/ab34-ladner-statement-validation');PRE=json.loads((B/'PREPARATION.json').read_text());label=sys.argv[1];file=sys.argv[2];snapshot=sys.argv[3] if len(sys.argv)>3 else PRE['snapshot'];D=B/'attempts'/label;D.mkdir();source=Path(file);actual=source if source.is_absolute() else Path(PRE['project'])/source;raw=actual.read_bytes();(D/'source.lean.txt').write_bytes(raw)
cmd=['bash',PRE['helper'],PRE['project'],snapshot,file];req={'utc':datetime.now(timezone.utc).isoformat(),'command':cmd,'source_commit':PRE['source_commit'],'actual_owner_SHA256':PRE['actual_source_SHA256'],'probe_SHA256':hashlib.sha256(raw).hexdigest(),'snapshot':snapshot,'local_slots':os.environ.get('TCSLIB_LEAN_SLOTS'),'own_jobs':1,'machine_cap':5,'no_olean_output':True};(D/'request.json').write_text(json.dumps(req,indent=2)+'\n');t=time.monotonic();raw_path=D/'raw.out'; stream=raw_path.open('wb'); r=subprocess.run(cmd,stdout=stream,stderr=subprocess.STDOUT); stream.close(); out=raw_path.read_bytes();receipt={**req,'exit':r.returncode,'seconds_including_slot_wait':time.monotonic()-t,'raw_bytes':len(out),'raw_SHA256':hashlib.sha256(out).hexdigest(),'errors':out.count(b'error:'),'sorry_warnings':out.count(b"declaration uses 'sorry'"),'source_unchanged':actual.read_bytes()==raw};(D/'run.json').write_text(json.dumps(receipt,indent=2)+'\n');print(json.dumps({k:receipt[k] for k in ['exit','seconds_including_slot_wait','raw_bytes','raw_SHA256','errors','sorry_warnings','source_unchanged']},indent=2));print('\n'.join(l for l in out.decode(errors='replace').splitlines() if l.startswith(('GUARDS|','SIMPDEFS|','SIMP-EXTRA|','COMPLETE|')) or 'error:' in l)[:16000])
